b'{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "opensip.product.enumeration-plan.1",
  "title": "EnumerationPlanV1 \xe2\x80\x94 Plan-bound expected population parameter (DRAFT, isolated successor)",
  "description": "Closed Draft 2020-12 parameter payload. Identity is raw SHA-256 of C(this record); not an H-domain. MUST NOT contain planId or analysisSpecDigest (parent-cycle). Cells are exactly analysis-spec requestedCapabilities ownership tuples. Program bindings are the Plan's explicit selected native resolved-input programs; U-1 default discovery does not enumerate every tsconfig variant. Exact typed admission (foundation/canonical.py) precedes validation. 4 MiB C-byte ceiling, no truncation. Standing: draft only; frozen21 and live repo untouched.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schemaVersion",
    "snapshotId",
    "scopeDigest",
    "membershipDigest",
    "cells"
  ],
  "properties": {
    "schemaVersion": {
      "const": 1
    },
    "snapshotId": {
      "type": "string",
      "pattern": "^snapshot2:[0-9a-f]{64}(?![\\s\\S])",
      "description": "The analysed snapshot. Closure (not a field of this preimage's parent hash) requires equality with plan.snapshotId."
    },
    "scopeDigest": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
      "x-opensip-digest": {
        "representation": "canonical-record",
        "retention": "preimage",
        "authority": "foundation",
        "record": {
          "bundle": "identity",
          "document": "foundation/identity-schemas.v3.json",
          "selector": "#/$defs/scope-descriptor"
        }
      },
      "description": "raw SHA-256 of C(scope-descriptor). Closure requires equality with plan.scopeDigest."
    },
    "membershipDigest": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
      "x-opensip-digest": {
        "representation": "canonical-record",
        "retention": "preimage",
        "authority": "native",
        "record": {
          "document": "native/native-evidence.schemas.v2.json",
          "selector": "#/$defs/UnitMembershipV1"
        }
      },
      "description": "raw SHA-256 of C(UnitMembershipV1). The typed preimage is retained under that digest. Closure recomputes C(retained membership) and compares. No JSON Schema $ref is used here so this document remains independently keyed as a parameter (payload-registry keys by full document bytes)."
    },
    "cells": {
      "type": "array",
      "minItems": 1,
      "maxItems": 1024,
      "uniqueItems": true,
      "items": {
        "$ref": "#/$defs/CellObligationV1"
      },
      "x-opensip-order": {
        "by": [
          "capabilityId",
          "languageMode",
          "workspaceRoot"
        ]
      },
      "x-opensip-uniqueness": {
        "ownershipTuple": [
          "capabilityId",
          "languageMode",
          "workspaceRoot"
        ],
        "law": "Exactly the analysis-spec requestedCapabilities ownership tuples, including required. Duplicate tuples refuse. cellOrdinal is the 0-based index in this sorted array after admission; it is not stored on the cell (storing it would be a self-id)."
      }
    }
  },
  "x-opensip-parameter-registry-extension": {
    "standing": "NEW, pending root payload-registry integration",
    "payloadClass": "parameter",
    "keyIsTheDocumentNotThePair": true,
    "document": "foundation/enumeration-plan.schema.v1.json",
    "selector": "#",
    "atMostOnePerSpec": true,
    "note": "analysis-spec.parameters[].schemaDigest is raw SHA-256 of this file's exact bytes; payloadDigest is raw SHA-256 of C(EnumerationPlanV1). Do not add a second $def from this document as another parameter row."
  },
  "x-opensip-kind-derivation": {
    "authority": "native/native-capability-matrix.v2.json#/capabilities[].relations plus foundation/relation-payload-schemas.v2.json#/x-opensip-relation-registry subjectKindLaw",
    "inventory": [
      "file",
      "package"
    ],
    "syntax": [
      "symbol"
    ],
    "imports": [
      "symbol"
    ],
    "references": [
      "symbol"
    ],
    "calls": [
      "symbol"
    ],
    "types": [
      "symbol"
    ],
    "reachability": [
      "symbol"
    ],
    "unresolved-edge": [
      "symbol"
    ],
    "clones-fact": [
      "file"
    ],
    "clones-near": [],
    "clones-cross-tsjs": [],
    "note": "kinds is stored on the cell. Candidate-only capabilities have an empty inventory kinds array; they still occupy one requestedCapabilities row and one cell. Empty kinds/extents do NOT mean complete-empty candidate work. Each available clones-near/clones-cross-tsjs binding MUST name candidateSourcePaths: the Plan-selected source-path census for that program, a subset of first-party scoped snapshot members under the cell workspace. Explicit [] is a selected empty census. Omitted field is not an empty census."
  },
  "x-opensip-file-membership-extent-law": {
    "membershipEnum": "native/native-evidence.schemas.v2.json#/$defs/FileMembershipRowV1/properties/membership",
    "membership": [
      "program-member",
      "syntax-only",
      "unsupported-file",
      "outside-project-boundary"
    ],
    "reasonEnum": "native/native-evidence.schemas.v2.json#/$defs/FileMembershipRowV1/properties/reason",
    "reason": [
      "deepest-unit-in-language",
      "no-program-unit-for-language",
      "grammar-only",
      "no-bundled-grammar",
      "host-ignore-convention",
      "nested-repository",
      "nested-project",
      "custody-excluded"
    ],
    "excludeAlways": [
      "membership=outside-project-boundary",
      "reason=host-ignore-convention",
      "reason=nested-repository",
      "reason=nested-project",
      "reason=custody-excluded"
    ],
    "fileKind": "Every remaining inventoried first-party snapshot path in the cell workspace/scope, including data-document, unsupported-file (no-bundled-grammar), extensionless, and syntax-only grammar-only members, regardless of compiler-mode program-member. Inventory is not grammar-gated.",
    "symbolKind": "Selected program/grammar CODE scope only: compiler-mode program-member paths whose suffix is a syntaxClass=code grammar, or syntax-only paths with a selected code grammar. Data-only selected symbol extents are lawful and may be complete-empty.",
    "packageKind": "First-party inventoried manifests only (package.json, Cargo.toml, and Cargo workspace memberPackageRoots manifests). Never node_modules, DependencySourceSet, or invented external snapshot paths."
  },
  "x-opensip-new-internal-faults": {
    "standing": "NEW/internal pending root public-registry integration. Not existing DomainDetailCode members.",
    "keys": [
      "ENUMERATION_PLAN_PROGRAM_BINDINGS_OVERFLOW",
      "ENUMERATION_PLAN_REQUIRED_UNSELECTED_ENUMERATOR",
      "ENUMERATION_PLAN_CELL_TUPLE_MISMATCH",
      "ENUMERATION_PLAN_MEMBERSHIP_DIGEST_MISMATCH",
      "ENUMERATION_PLAN_SCOPE_DIGEST_MISMATCH",
      "ENUMERATION_PLAN_SNAPSHOT_MISMATCH",
      "ENUMERATION_BINDING_CONTEXT_NOT_IN_PLAN",
      "ENUMERATION_BINDING_UNIVERSE_NOT_BOUND_TO_SELECTED_CONTEXT",
      "ENUMERATION_BINDING_ENUMERATOR_NOT_IN_PLAN",
      "ENUMERATION_CANDIDATE_SOURCE_PATHS",
      "ENUMERATION_MEMBERSHIP_ORDER",
      "ENUMERATION_MEMBERSHIP_ROW_DERIVATION"
    ]
  },
  "$defs": {
    "DigestHex": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}(?![\\s\\S])"
    },
    "WorkspaceRootText": {
      "type": "string",
      "minLength": 1,
      "maxLength": 4096,
      "description": "Same type as analysis-spec.requestedCapabilities[].workspaceRoot (identity-schemas.v3.json#/$defs/Text). MAY be '.' for the admitted project root (native-evidence.md \xc2\xa71.4 normalize_explicit_root). NOT LogicalPath, which forbids a dot segment."
    },
    "LogicalPath": {
      "type": "string",
      "minLength": 1,
      "maxLength": 4096,
      "pattern": "^[^/\\\\\\u0000]{1,255}(/[^/\\\\\\u0000]{1,255})*(?![\\s\\S])",
      "not": {
        "pattern": "(^|/)\\.\\.?(/|$)"
      },
      "description": "Byte-identical constraint to identity-schemas.v3.json#/$defs/LogicalPath. File inventory paths, not workspaceRoot."
    },
    "ClosureId": {
      "type": "string",
      "pattern": "^closure2:[0-9a-f]{64}(?![\\s\\S])"
    },
    "CapabilityId": {
      "type": "string",
      "enum": [
        "inventory",
        "syntax",
        "imports",
        "references",
        "calls",
        "types",
        "reachability",
        "clones-fact",
        "clones-near",
        "clones-cross-tsjs",
        "unresolved-edge"
      ],
      "description": "native/native-capability-matrix.v2.json#/capabilityIdLaw.members"
    },
    "LanguageMode": {
      "type": "string",
      "enum": [
        "ts-tsconfig",
        "js-allowjs",
        "js-synthesized",
        "rust-cargo",
        "rust-cargo-prepared",
        "syntax-only"
      ],
      "description": "identity-schemas.v3.json#/x-opensip-digest-domains/languageModes/map keys"
    },
    "SubjectKind": {
      "type": "string",
      "enum": [
        "file",
        "symbol",
        "package"
      ]
    },
    "DeficiencyV2": {
      "type": "string",
      "enum": [
        "language-tier-unsupported",
        "provider-unavailable",
        "input-closure-incomplete",
        "budget-exhausted",
        "confidence-floor-unmet",
        "derivation-policy-unmet",
        "resolution-incomplete",
        "external-consumers-unknown",
        "required-relation-missing"
      ],
      "description": "Copied closed membership of native-evidence.schemas.v2.json#/$defs/DeficiencyV2. Drift vs that enum is a defect."
    },
    "NativeCause": {
      "type": "string",
      "enum": [
        "body-language-owner-ambiguous",
        "body-language-owner-unenumerated",
        "body-language-ownership-missing",
        "capability-missing",
        "config-flag-stripped",
        "generated-file-missing",
        "generated-file-out-of-bounds",
        "generated-output-unavailable",
        "linker-unavailable",
        "lockfile-missing",
        "missing-dependency-source",
        "no-program-unit",
        "node-modules-outside-read-set",
        "source-replacement-outside-snapshot"
      ],
      "description": "Copied closed membership of native-evidence.schemas.v2.json#/$defs/NativeCause."
    },
    "SelectedEnumeratorRef": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "status",
        "closureId"
      ],
      "description": "A selected provider closure. Missing capability/provider selection for a required cell refuses pre-Plan (no fictional closure). Executable unavailability with this selected closure is UnavailableProgramBindingV1, not an unselected enumerator.",
      "properties": {
        "status": {
          "const": "selected"
        },
        "closureId": {
          "$ref": "#/$defs/ClosureId"
        }
      }
    },
    "UnselectedEnumeratorRef": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "status",
        "reason"
      ],
      "description": "Optional-cell enumerator not selected. Lawful only on UnavailableProgramBindingV1 when the cell required=false. Not PROVIDER.NOT_SELECTED (matrix cell never mints a cell here). closureId is absent: a selected enumerator with a missing closure pointer is structural, not this shape.",
      "properties": {
        "status": {
          "const": "unselected"
        },
        "reason": {
          "const": "optional-unselected"
        }
      }
    },
    "EnumeratorRef": {
      "oneOf": [
        {
          "$ref": "#/$defs/SelectedEnumeratorRef"
        },
        {
          "$ref": "#/$defs/UnselectedEnumeratorRef"
        }
      ],
      "description": "Available bindings may only use SelectedEnumeratorRef. Unavailable bindings may use either: selected+unavailable execution/input, or unselected optional-unselected when required=false."
    },
    "KindExtentV1": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "kind",
        "paths"
      ],
      "properties": {
        "kind": {
          "$ref": "#/$defs/SubjectKind"
        },
        "paths": {
          "type": "array",
          "maxItems": 100000,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/LogicalPath"
          },
          "x-opensip-order": "canonical-set",
          "description": "Per-kind expected paths. File, symbol and package extents MAY differ. Empty is lawful."
        }
      }
    },
    "AvailableProgramBindingV1": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "ordinal",
        "provenance",
        "enumerator",
        "nativeContextDigest",
        "universe",
        "programEntry",
        "extents"
      ],
      "properties": {
        "ordinal": {
          "type": "integer",
          "minimum": 0,
          "maximum": 127
        },
        "provenance": {
          "type": "string",
          "enum": [
            "default-unit",
            "explicit-plan-selection"
          ]
        },
        "enumerator": {
          "$ref": "#/$defs/SelectedEnumeratorRef"
        },
        "nativeContextDigest": {
          "$ref": "#/$defs/DigestHex",
          "x-opensip-digest": {
            "representation": "h-identity",
            "retention": "preimage",
            "authority": "native",
            "domainSet": "native-context"
          },
          "description": "Bare 64-hex suffix of the selected native context H identity. Must be a member of plan.nativeContextDigests at closure. NEW ENUMERATION_BINDING_CONTEXT_NOT_IN_PLAN if not. Outcome must not introduce a context this field did not name."
        },
        "universe": {
          "$ref": "#/$defs/DigestHex",
          "x-opensip-digest": {
            "representation": "h-identity",
            "retention": "preimage",
            "authority": "native",
            "domainSet": "native-semantic-universe"
          }
        },
        "programEntry": {
          "oneOf": [
            {
              "$ref": "#/$defs/LogicalPath"
            },
            {
              "type": "null"
            }
          ],
          "description": "TS/JS extra program: non-null LogicalPath of the selected inventoried config (snapshot member). U-1 default uses null; admission derives the actual U-1 marker/synthesized entry and compares it to retained TypeScriptConfigGraphV1.entryConfigPath (the graph entry need not be null). Rust extra programs are distinct universe H values (cfg/features/ownership); programEntry is not a complete program key. Resolved-input H remains authority."
        },
        "extents": {
          "type": "array",
          "minItems": 0,
          "maxItems": 3,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/KindExtentV1"
          },
          "x-opensip-order": {
            "by": [
              "kind"
            ]
          }
        },
        "candidateSourcePaths": {
          "type": "array",
          "maxItems": 100000,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/LogicalPath"
          },
          "x-opensip-order": "canonical-set",
          "description": "Plan-selected candidate source-path census for clones-near/clones-cross-tsjs. Required on those cells' available bindings. Subset of first-party scoped snapshot members under the cell workspace. Not the whole monorepo unless the Plan selected that set. Explicit empty array is a selected zero-path census; omitting the field is not complete-empty work. Inventory cells must omit this field."
        }
      }
    },
    "UnavailableProgramBindingV1": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "ordinal",
        "provenance",
        "enumerator",
        "nativeContextDigest",
        "universe",
        "programEntry",
        "extents",
        "deficiency",
        "nativeCause"
      ],
      "properties": {
        "ordinal": {
          "type": "integer",
          "minimum": 0,
          "maximum": 127
        },
        "provenance": {
          "type": "string",
          "enum": [
            "default-unit",
            "explicit-plan-selection"
          ]
        },
        "enumerator": {
          "$ref": "#/$defs/EnumeratorRef"
        },
        "nativeContextDigest": {
          "oneOf": [
            {
              "$ref": "#/$defs/DigestHex"
            },
            {
              "type": "null"
            }
          ],
          "x-opensip-digest": {
            "representation": "h-identity",
            "retention": "preimage",
            "authority": "native",
            "domainSet": "native-context",
            "nullable": true
          }
        },
        "universe": {
          "type": "null"
        },
        "programEntry": {
          "oneOf": [
            {
              "$ref": "#/$defs/LogicalPath"
            },
            {
              "type": "null"
            }
          ]
        },
        "extents": {
          "type": "array",
          "minItems": 0,
          "maxItems": 3,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/KindExtentV1"
          },
          "x-opensip-order": {
            "by": [
              "kind"
            ]
          }
        },
        "candidateSourcePaths": {
          "type": "array",
          "maxItems": 100000,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/LogicalPath"
          },
          "x-opensip-order": "canonical-set"
        },
        "deficiency": {
          "$ref": "#/$defs/DeficiencyV2"
        },
        "nativeCause": {
          "oneOf": [
            {
              "$ref": "#/$defs/NativeCause"
            },
            {
              "type": "null"
            }
          ]
        }
      }
    },
    "ProgramBindingV1": {
      "oneOf": [
        {
          "$ref": "#/$defs/AvailableProgramBindingV1"
        },
        {
          "$ref": "#/$defs/UnavailableProgramBindingV1"
        }
      ]
    },
    "CellObligationV1": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "capabilityId",
        "languageMode",
        "workspaceRoot",
        "required",
        "kinds",
        "programBindings"
      ],
      "properties": {
        "capabilityId": {
          "$ref": "#/$defs/CapabilityId"
        },
        "languageMode": {
          "$ref": "#/$defs/LanguageMode"
        },
        "workspaceRoot": {
          "$ref": "#/$defs/WorkspaceRootText"
        },
        "required": {
          "type": "boolean",
          "description": "Copied from requestedCapabilities[].required (existing boolean ownership attribute). Required execution of this cell is independent of whether any policy rule is disabled."
        },
        "kinds": {
          "type": "array",
          "minItems": 0,
          "maxItems": 3,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/SubjectKind"
          },
          "x-opensip-order": "canonical-set"
        },
        "programBindings": {
          "type": "array",
          "minItems": 1,
          "maxItems": 128,
          "items": {
            "$ref": "#/$defs/ProgramBindingV1"
          },
          "x-opensip-order": "ordinal",
          "description": "Contiguous ordinal 0..n-1. maxItems 128 is THIS array's bound, NOT plan.nativeContextDigests maxItems 128. Overflow refuses ENUMERATION_PLAN_PROGRAM_BINDINGS_OVERFLOW (NEW/internal). Multiple bindings per cell are allowed; one context never implies one universe. Duplicate available universe H inside one cell refuses ENUMERATION_BINDING_DUPLICATE_UNIVERSE. provenance=default-unit at most once and only at ordinal 0."
        }
      }
    }
  }
}
'

