    "SyntaxUniverseV2ResolvedInputs": {
      "type": "object",
      "additionalProperties": false,
      "description": "The universe of the syntax-only mode. Its identity is the admitted grammar context plus the SELECTED grammar set for this analysis: selecting a different grammar set is a different universe, exactly as selecting different compilation targets is for Rust, so what was parsed is visible to every consumer rather than being an invisible default. It carries the constant resolutionAttempted=false so no consumer can read a syntax-only universe as a resolution claim: semantic rungs under it are language-tier-unsupported, not merely absent.",
      "required": [
