          "x-opensip-order": "utf8",
          "description": "A subset of the context bundle's grammarIds. Admission refuses a selection naming a grammar the bundle does not contain; an empty selection is not expressible, because a universe that parsed nothing could not have produced a fact."
        },
        "resolutionAttempted": {
          "const": false
        }
      }
    },
